func name*(n: Node): Node = n.son(lbName)
func value*(n: Node): Node = n.son(lbValue)
func key*(n: Node): Node = n.son(lbKey)
func open*(n: Node): Node = n.son(lbOpen)
func close*(n: Node): Node = n.son(lbClose)
func altLabel*(n: Node): Node = n.son(lbAltLabel)
func arg*(n: Node): Node = n.son(lbArg)
func op*(n: Node): Node = n.son(lbOp)
func lazy*(n: Node): Node = n.son(lbLazy)

proc ruleFile(p: var Parser, returnState: int): Node
proc ruleTopLevel(p: var Parser, returnState: int): Node
proc ruleOptions(p: var Parser, returnState: int): Node
proc ruleOption(p: var Parser, returnState: int): Node
proc ruleTokens(p: var Parser, returnState: int): Node
proc ruleTokenNames(p: var Parser, returnState: int): Node
proc ruleIndentation(p: var Parser, returnState: int): Node
proc ruleSetting(p: var Parser, returnState: int): Node
proc ruleBracket(p: var Parser, returnState: int): Node
proc ruleRule(p: var Parser, returnState: int): Node
proc ruleRuleAlt(p: var Parser, returnState: int): Node
proc ruleAssoc(p: var Parser, returnState: int): Node
proc ruleCommand(p: var Parser, returnState: int): Node
proc ruleElement(p: var Parser, returnState: int): Node
proc ruleAtom(p: var Parser, returnState: int): Node
proc rulePrimary(p: var Parser, returnState: int): Node
proc ruleSubAlt(p: var Parser, returnState: int): Node
proc ruleSuffix(p: var Parser, returnState: int): Node

proc ruleFile(p: var Parser, returnState: int): Node =
  ## `file`, line 9
  result = p.newNode(nkFile)
  p.enter(0, returnState, 0)
  try:
    p.match(result, tkGrammar)
    p.match(result, tkID, lbName)
    p.match(result, tkSemi)
    while p.more(result, {tkFragment, tkID, tkOPTIONS, tkTOKENS, tkINDENTATION},
        {tkEOF}):
      result.add(ruleTopLevel(p, 4))
    p.match(result, tkEOF)
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleTopLevel(p: var Parser, returnState: int): Node =
  ## `topLevel`, line 10
  result = p.newNode(nkTopLevel)
  p.enter(1, returnState, 0)
  try:
    case p.peek
    of tkOPTIONS:
      result.add(ruleOptions(p, 10))
    of tkTOKENS:
      result.add(ruleTokens(p, 12))
    of tkINDENTATION:
      result.add(ruleIndentation(p, 14))
    of tkFragment, tkID:
      result.add(ruleRule(p, 16))
    else:
      p.fail({tkFragment, tkID, tkOPTIONS, tkTOKENS, tkINDENTATION})
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleOptions(p: var Parser, returnState: int): Node =
  ## `options`, line 12
  result = p.newNode(nkOptions)
  p.enter(2, returnState, 0)
  try:
    p.match(result, tkOPTIONS)
    while p.more(result, {tkID}, {tkRBrace}):
      result.add(ruleOption(p, 19))
    p.match(result, tkRBrace)
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleOption(p: var Parser, returnState: int): Node =
  ## `option`, line 13
  result = p.newNode(nkOption)
  p.enter(3, returnState, 0)
  try:
    p.match(result, tkID, lbName)
    p.match(result, tkEq)
    p.matchSet(result, {tkID, tkINT, tkSTRING}, lbValue)
    p.match(result, tkSemi)
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleTokens(p: var Parser, returnState: int): Node =
  ## `tokens`, line 14
  result = p.newNode(nkTokens)
  p.enter(4, returnState, 0)
  try:
    p.match(result, tkTOKENS)
    if p.peek in {tkID}:
      result.add(ruleTokenNames(p, 36))
    else:
      p.expect({tkID})
    p.match(result, tkRBrace)
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleTokenNames(p: var Parser, returnState: int): Node =
  ## `tokenNames`, line 15
  result = p.newNode(nkTokenNames)
  p.enter(5, returnState, 0)
  try:
    p.match(result, tkID)
    if p.peek in {tkComma}:
      p.match(result, tkComma)
      if p.peek in {tkID}:
        result.add(ruleTokenNames(p, 39))
      else:
        p.expect({tkID})
    else:
      p.expect({tkComma})
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleIndentation(p: var Parser, returnState: int): Node =
  ## `indentation`, line 16
  result = p.newNode(nkIndentation)
  p.enter(6, returnState, 0)
  try:
    p.match(result, tkINDENTATION)
    while p.more(result, {tkID}, {tkRBrace}):
      result.add(ruleSetting(p, 46))
    p.match(result, tkRBrace)
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleSetting(p: var Parser, returnState: int): Node =
  ## `setting`, line 17
  result = p.newNode(nkSetting)
  p.enter(7, returnState, 0)
  try:
    p.match(result, tkID, lbKey)
    p.match(result, tkEq)
    case p.peek
    of tkID, tkINT:
      p.matchSet(result, {tkID, tkINT}, lbValue)
    of tkSTRING:
      result.add(ruleBracket(p, 62))
      while p.more(result, {tkComma}, {tkSemi}):
        p.match(result, tkComma)
        result.add(ruleBracket(p, 62))
    else:
      p.fail({tkID, tkINT, tkSTRING})
    p.match(result, tkSemi)
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleBracket(p: var Parser, returnState: int): Node =
  ## `bracket`, line 18
  result = p.newNode(nkBracket)
  p.enter(8, returnState, 0)
  try:
    p.match(result, tkSTRING, lbOpen)
    p.match(result, tkSTRING, lbClose)
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleRule(p: var Parser, returnState: int): Node =
  ## `rule`, line 20
  result = p.newNode(nkRule)
  p.enter(9, returnState, 0)
  try:
    if p.peek in {tkFragment}:
      p.match(result, tkFragment)
    else:
      p.expect({tkFragment})
    p.match(result, tkID, lbName)
    p.match(result, tkColon)
    result.add(ruleRuleAlt(p, 74))
    while p.more(result, {tkPipe}, {tkSemi}):
      p.match(result, tkPipe)
      result.add(ruleRuleAlt(p, 74))
    p.match(result, tkSemi)
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleRuleAlt(p: var Parser, returnState: int): Node =
  ## `ruleAlt`, line 21
  result = p.newNode(nkRuleAlt)
  p.enter(10, returnState, 0)
  try:
    if p.peek in {tkLt}:
      result.add(ruleAssoc(p, 80))
    else:
      p.expect({tkLt})
    while p.more(result, {tkLParen, tkDot, tkTilde, tkID, tkSTRING, tkCHARSET},
        {tkSemi, tkPipe, tkHash, tkMinusGt}):
      result.add(ruleElement(p, 80))
    if p.peek in {tkHash}:
      p.match(result, tkHash)
      p.match(result, tkID, lbAltLabel)
    else:
      p.expect({tkHash})
    if p.peek in {tkMinusGt}:
      p.match(result, tkMinusGt)
      result.add(ruleCommand(p, 89))
      while p.more(result, {tkComma}, {tkSemi, tkPipe}):
        p.match(result, tkComma)
        result.add(ruleCommand(p, 89))
    else:
      p.expect({tkMinusGt})
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleAssoc(p: var Parser, returnState: int): Node =
  ## `assoc`, line 22
  result = p.newNode(nkAssoc)
  p.enter(11, returnState, 0)
  try:
    p.match(result, tkLt)
    p.match(result, tkID, lbKey)
    p.match(result, tkEq)
    p.match(result, tkID, lbValue)
    p.match(result, tkGt)
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleCommand(p: var Parser, returnState: int): Node =
  ## `command`, line 23
  result = p.newNode(nkCommand)
  p.enter(12, returnState, 0)
  try:
    p.match(result, tkID, lbName)
    if p.peek in {tkLParen}:
      p.match(result, tkLParen)
      p.match(result, tkID, lbArg)
      p.match(result, tkRParen)
    else:
      p.expect({tkLParen})
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleElement(p: var Parser, returnState: int): Node =
  ## `element`, line 24
  p.enter(13, returnState, 0)
  try:
    case p.peek
    of tkID:
      result = p.newNode(nkIdElement)
      p.match(result, tkID)
      if p.peek in {tkEq}:
        p.match(result, tkEq)
        result.add(ruleAtom(p, 109))
      else:
        p.expect({tkEq})
      if p.peek in {tkQuestion, tkStar, tkPlus}:
        result.add(ruleSuffix(p, 107))
      else:
        p.expect({tkQuestion, tkStar, tkPlus})
    of tkLParen, tkDot, tkTilde, tkSTRING, tkCHARSET:
      result = p.newNode(nkPlainElement)
      result.add(rulePrimary(p, 115))
      if p.peek in {tkQuestion, tkStar, tkPlus}:
        result.add(ruleSuffix(p, 114))
      else:
        p.expect({tkQuestion, tkStar, tkPlus})
    else:
      p.fail({tkLParen, tkDot, tkTilde, tkID, tkSTRING, tkCHARSET})
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleAtom(p: var Parser, returnState: int): Node =
  ## `atom`, line 27
  result = p.newNode(nkAtom)
  p.enter(14, returnState, 0)
  try:
    case p.peek
    of tkID:
      p.match(result, tkID)
    of tkLParen, tkDot, tkTilde, tkSTRING, tkCHARSET:
      result.add(rulePrimary(p, 122))
    else:
      p.fail({tkLParen, tkDot, tkTilde, tkID, tkSTRING, tkCHARSET})
  except SyntaxError:
    p.recover(result)
  p.leave()

proc rulePrimary(p: var Parser, returnState: int): Node =
  ## `primary`, line 28
  p.enter(15, returnState, 0)
  try:
    case p.peek
    of tkSTRING:
      result = p.newNode(nkLiteral)
      p.match(result, tkSTRING)
      if p.peek in {tkDotDot}:
        p.match(result, tkDotDot)
        p.match(result, tkSTRING)
      else:
        p.expect({tkDotDot})
    of tkCHARSET:
      result = p.newNode(nkCharSet)
      p.match(result, tkCHARSET)
    of tkDot:
      result = p.newNode(nkWildcard)
      p.match(result, tkDot)
    of tkTilde:
      result = p.newNode(nkNot)
      p.match(result, tkTilde)
      result.add(ruleAtom(p, 135))
    of tkLParen:
      result = p.newNode(nkBlock)
      p.match(result, tkLParen)
      result.add(ruleSubAlt(p, 140))
      while p.more(result, {tkPipe}, {tkRParen}):
        p.match(result, tkPipe)
        result.add(ruleSubAlt(p, 140))
      p.match(result, tkRParen)
    else:
      p.fail({tkLParen, tkDot, tkTilde, tkSTRING, tkCHARSET})
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleSubAlt(p: var Parser, returnState: int): Node =
  ## `subAlt`, line 34
  result = p.newNode(nkSubAlt)
  p.enter(16, returnState, 0)
  try:
    while p.more(result, {tkLParen, tkDot, tkTilde, tkID, tkSTRING, tkCHARSET},
        {tkPipe, tkRParen}):
      result.add(ruleElement(p, 144))
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleSuffix(p: var Parser, returnState: int): Node =
  ## `suffix`, line 35
  result = p.newNode(nkSuffix)
  p.enter(17, returnState, 0)
  try:
    p.matchSet(result, {tkQuestion, tkStar, tkPlus}, lbOp)
    if p.peek in {tkQuestion}:
      p.match(result, tkQuestion, lbLazy)
    else:
      p.expect({tkQuestion})
  except SyntaxError:
    p.recover(result)
  p.leave()

const followSets: array[18, set[TokenKind]] = [
  {tkEOF}, # file
  {tkEOF, tkFragment, tkID, tkOPTIONS, tkTOKENS, tkINDENTATION}, # topLevel
  {tkEOF, tkFragment, tkID, tkOPTIONS, tkTOKENS, tkINDENTATION}, # options
  {tkEOF, tkRBrace, tkID}, # option
  {tkEOF, tkFragment, tkID, tkOPTIONS, tkTOKENS, tkINDENTATION}, # tokens
  {tkEOF, tkRBrace}, # tokenNames
  {tkEOF, tkFragment, tkID, tkOPTIONS, tkTOKENS, tkINDENTATION}, # indentation
  {tkEOF, tkRBrace, tkID}, # setting
  {tkEOF, tkSemi, tkComma}, # bracket
  {tkEOF, tkFragment, tkID, tkOPTIONS, tkTOKENS, tkINDENTATION}, # rule
  {tkEOF, tkSemi, tkPipe}, # ruleAlt
  {tkEOF, tkSemi, tkPipe, tkHash, tkMinusGt, tkLParen, tkDot, tkTilde, tkID,
      tkSTRING, tkCHARSET}, # assoc
  {tkEOF, tkSemi, tkComma, tkPipe}, # command
  {tkEOF, tkSemi, tkPipe, tkHash, tkMinusGt, tkLParen, tkRParen, tkDot, tkTilde,
      tkID, tkSTRING, tkCHARSET}, # element
  {tkEOF, tkSemi, tkPipe, tkHash, tkMinusGt, tkLParen, tkRParen, tkDot, tkTilde,
      tkQuestion, tkStar, tkPlus, tkID, tkSTRING, tkCHARSET}, # atom
  {tkEOF, tkSemi, tkPipe, tkHash, tkMinusGt, tkLParen, tkRParen, tkDot, tkTilde,
      tkQuestion, tkStar, tkPlus, tkID, tkSTRING, tkCHARSET}, # primary
  {tkEOF, tkPipe, tkRParen}, # subAlt
  {tkEOF, tkSemi, tkPipe, tkHash, tkMinusGt, tkLParen, tkRParen, tkDot, tkTilde,
      tkID, tkSTRING, tkCHARSET}] # suffix

const ruleNames = ["file", "topLevel", "options", "option", "tokens",
    "tokenNames", "indentation", "setting", "bracket", "rule", "ruleAlt",
    "assoc", "command", "element", "atom", "primary", "subAlt", "suffix"]

proc follows(rule, kind: int): bool = TokenKind(kind) in followSets[rule]

func foundKind*(e: SyntaxErrorInfo): TokenKind =
  ## The kind of the token a syntax error found, if `e.hasToken`.
  TokenKind(e.found)

func expectedKinds*(e: SyntaxErrorInfo): seq[TokenKind] =
  ## The kinds of the tokens that could have come where a syntax error is.
  for k in e.expected: result.add TokenKind(k)

proc parseWith(src, filename: string, formatter: SyntaxErrorFormatter,
    rule: proc (p: var Parser): Node {.nimcall.}): ParseResult[Node] =
  result.diagnostics.filename = filename
  let tokens = tokenize(src, result.diagnostics)
  result.tree = runParser[NodeKind, NodeLabel, TokenKind](tokens, src,
    result.diagnostics, @ruleNames, follows, rule)
  result.diagnostics.formatSyntaxErrors(formatter)

